#include "dual_state_cuda_optimizer.cuh"
#include <cstdio>
int main(){try{using namespace tao::dual;Vec w{1,-1,.1f,0,0,0,0,0};Device W(w),Q(8),S(2);ds_project<<<1,32>>>(W.p,Q.p,S.p,2,4);check(cudaGetLastError());auto q=Q.host(),s=S.host();Vec expected{1,-1,0,0,0,0,0,0};if(q!=expected||s[0]!=1||s[1]!=1)throw std::runtime_error("projection");Vec weights{.5f,-.25f},grads{.2f,-.4f};Device A(weights),G(grads),M(Vec(2)),V(Vec(2));ds_adamw<<<1,32>>>(A.p,G.p,M.p,V.p,2,.5f,.0003f,.01f,.1f,.001f);check(cudaGetLastError());auto a=A.host();double worst=0;for(int i=0;i<2;++i){double g=grads[i]*.5;double ref=weights[i]-.0003*(g/(std::abs(g)+1e-8)+.01*weights[i]);worst=std::max(worst,std::abs(ref-a[i]));}if(worst>1e-7)throw std::runtime_error("adam");printf("PASS projection ties/zero and AdamW max_error=%.9g\n",worst);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
